<script setup>
import { ref } from 'vue'
import { login, session } from '../api'
defineProps({admin:Boolean})
const account=ref(''), password=ref(''), busy=ref(false), error=ref(''), help=ref(false)
async function submit(admin) { if(busy.value)return; busy.value=true; error.value=''; try { await login(account.value.trim(),password.value,admin); password.value='' } catch(e) { error.value=e.message+(e.retryAfter?`，请在 ${e.retryAfter} 秒后重试`:'') } finally { busy.value=false } }
</script>
<template><main class="login-layout"><section class="login-story"><a href="/" class="brand">杭电失物招领</a><div><span class="eyebrow">LOST & FOUND · HDU</span><h1>让每一份牵挂，<br>都有回音。</h1><p>找回遗失的小物件，连接校园里的善意。<br>从一条信息开始，让物品回到主人身边。</p><div class="illustration" aria-hidden="true"><div class="orbit"></div><div class="object-card">⌕<span>寻找 · 遇见 · 归还</span></div></div></div><small>仅面向已验证的校园账号开放</small></section><section class="login-panel"><div class="login-form"><span class="eyebrow">{{admin?'管理工作台':'欢迎回来'}}</span><h2>{{ admin?'管理员登录':'登录校园账号' }}</h2><p class="muted">使用学号 / 职工号与平台密码登录</p><form @submit.prevent="submit(admin)"><label>学号 / 职工号<input v-model="account" autocomplete="username" required placeholder="请输入账号"></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required placeholder="请输入密码"></label><p v-if="error||session.notice" class="error" role="alert">{{error||session.notice}}</p><button class="primary wide" :disabled="busy">{{busy?'正在登录…':'登录'}}</button></form><button class="text-button" @click="help=!help">忘记密码？</button><p v-if="help" class="notice">请线下联系平台管理员核实身份并重置密码。首次使用临时密码登录后，需要设置新密码。</p><p class="fine">登录后可查看帖子和联系方式。请妥善保护自己的账号。</p><a :href="admin?'/':'/admin'" class="muted">{{admin?'返回用户端':'管理员入口'}} →</a></div></section></main></template>
